<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { BadgeDollarSign, Building2, CalendarDays, Check, ChevronDown, CircleAlert, Clock3, CreditCard, Download, LayoutDashboard, LogOut, RefreshCw, Search, ShieldCheck, ShieldOff, TrendingUp, Users, WalletCards, X } from '@lucide/vue'
import { api } from '../api'
import { useAuthStore } from '../stores/auth'

type Company = { id: number; name: string; slug: string; created_at: string; owner: {name:string;email:string}|null; status: string; is_suspended: boolean; suspension_reason: string|null; plan: string|null; subscription_ends_at: string|null; active_members: number; leads: number; listings: number; deals: number }
type Plan = {id:number;name:string;slug:string;monthly_price_minor:number|null;yearly_price_minor:number|null}
const auth = useAuthStore()
const route = useRoute(); const router = useRouter()
type PlatformTab = 'overview'|'companies'|'finance'|'paymob'
const platformTabs: PlatformTab[] = ['overview', 'companies', 'finance', 'paymob']
const tab = computed<PlatformTab>({
  get: () => platformTabs.includes(route.query.tab as PlatformTab) ? route.query.tab as PlatformTab : 'overview',
  set: (value) => { void router.replace({ path: route.path, query: { ...route.query, tab: value === 'overview' ? undefined : value } }) },
})
const overview = ref<any>(null); const companies = ref<Company[]>([]); const plans = ref<Plan[]>([])
const page = ref(1); const lastPage = ref(1); const totalCompanies = ref(0); const search = ref(''); const statusFilter = ref('all')
const from = ref(new Date(Date.now()-29*86400000).toISOString().slice(0,10)); const to = ref(new Date().toISOString().slice(0,10))
const loading = ref(true); const saving = ref(false); const error = ref(''); const selected = ref<Company|null>(null); const action = ref<'suspend'|'renew'|null>(null)
const form = ref({reason:'',plan_id:0,billing_cycle:'month',periods:1,renewal_mode:'extend'})
const gateway = ref<any>({configured:false,source:'none',integration_count:0,api_base:'https://accept.paymob.com',checkout_base:'https://accept.paymob.com/unifiedcheckout'})
const gatewayForm = ref({secret_key:'',public_key:'',hmac_secret:'',payment_methods:'',iframe_id:'',api_base:'https://accept.paymob.com',checkout_base:'https://accept.paymob.com/unifiedcheckout'})
const trendPoints = computed(() => { const items=overview.value?.revenue_series||[]; if(!items.length)return ''; const max=Math.max(1,...items.map((item:any)=>item.amount_minor)); return items.map((item:any,index:number)=>`${index*1100/(items.length-1)},${96-(item.amount_minor/max)*84}`).join(' ') })
const money = (minor:number|null|undefined) => new Intl.NumberFormat('en-EG',{style:'currency',currency:'EGP',maximumFractionDigits:0}).format((minor||0)/100)
const count = (value:number|undefined) => new Intl.NumberFormat('en-EG').format(value||0)
const date = (value:string|null|undefined) => value ? new Intl.DateTimeFormat('en-EG',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(value)) : '—'
const statusName = (value:string) => ({active:'Paid',trial:'Free trial',scheduled:'Scheduled',expired:'Expired',suspended:'Suspended',no_plan:'No plan'} as Record<string,string>)[value]||value
async function loadOverview(){ const {data}=await api.get('/platform/overview',{params:{from:from.value,to:to.value}}); overview.value=data }
async function loadCompanies(){ const {data}=await api.get('/platform/companies',{params:{page:page.value,search:search.value,status:statusFilter.value}}); companies.value=data.data; lastPage.value=data.meta.last_page; totalCompanies.value=data.meta.total }
async function load(){ loading.value=true; error.value=''; try { const results=await Promise.all([loadOverview(),loadCompanies(),api.get('/subscription-plans'),api.get('/platform/paymob-settings')]); plans.value=results[2].data.data.filter((p:Plan)=>p.slug!=='free-trial');gateway.value=results[3].data;gatewayForm.value={secret_key:gateway.value.secret_key||'',public_key:gateway.value.public_key||'',hmac_secret:gateway.value.hmac_secret||'',payment_methods:(gateway.value.payment_methods||[]).join(', '),iframe_id:gateway.value.iframe_id||'',api_base:gateway.value.api_base,checkout_base:gateway.value.checkout_base} } catch(e:any){error.value=e.response?.data?.message||'Could not load platform data.'} finally{loading.value=false} }
async function saveGateway(){saving.value=true;error.value='';try{await api.put('/platform/paymob-settings',{...gatewayForm.value,payment_methods:gatewayForm.value.payment_methods.split(',').map((value:string)=>Number(value.trim())).filter((value:number)=>Number.isInteger(value)&&value>0)});await load()}catch(e:any){error.value=e.response?.data?.errors?.payment_methods?.[0]||e.response?.data?.message||'Paymob settings could not be saved.'}finally{saving.value=false}}
function openAction(company:Company,next:'suspend'|'renew'){selected.value=company;action.value=next;form.value={reason:'',plan_id:plans.value.find(p=>p.slug==='professional')?.id||plans.value[0]?.id||0,billing_cycle:'month',periods:1,renewal_mode:'extend'} }
async function submitAction(){if(!selected.value||!action.value)return;saving.value=true;error.value='';try{const url=`/platform/companies/${selected.value.id}`;if(action.value==='suspend')await api.post(`${url}/suspend`,{reason:form.value.reason});else await api.post(`${url}/renew`,form.value);selected.value=null;action.value=null;await load()}catch(e:any){error.value=e.response?.data?.errors?.reason?.[0]||e.response?.data?.message||'Action could not be completed.'}finally{saving.value=false}}
async function reactivate(company:Company){saving.value=true;error.value='';try{await api.post(`/platform/companies/${company.id}/activate`,{reason:'Reactivated from platform console.'});await load()}catch(e:any){error.value=e.response?.data?.message||'Company could not be reactivated.'}finally{saving.value=false}}
async function logout(){await auth.logout();window.location.assign('/login')}
async function changePage(direction:number){page.value=Math.min(lastPage.value,Math.max(1,page.value+direction));await loadCompanies()}
function downloadCompanies(){const rows=[['Company','Owner','Email','Status','Plan','Members','Leads','Listings','Deals'],...companies.value.map(c=>[c.name,c.owner?.name||'',c.owner?.email||'',statusName(c.status),c.plan||'',c.active_members,c.leads,c.listings,c.deals])];const csv=rows.map(row=>row.map(value=>`"${String(value).split('"').join('""')}"`).join(',')).join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));link.download='exousia-companies.csv';link.click();URL.revokeObjectURL(link.href)}
onMounted(load)
</script>

<template>
  <main class="platform-admin">
    <aside class="platform-sidebar"><div class="platform-brand"><div class="platform-logo">E</div><div><strong>EXOUSIA</strong><small>PLATFORM CONTROL</small></div></div><div class="platform-admin-card"><span class="platform-avatar">{{ (auth.platformUser?.name||'A').slice(0,1).toUpperCase() }}</span><span><small>SUPER ADMIN</small><strong>{{ auth.platformUser?.name }}</strong></span><ShieldCheck :size="16" /></div><span class="platform-nav-label">MANAGEMENT</span><nav><button :class="{active:tab==='overview'}" @click="tab='overview'"><LayoutDashboard :size="18"/>Overview</button><button :class="{active:tab==='companies'}" @click="tab='companies';loadCompanies()"><Building2 :size="18"/>Companies<span>{{ count(overview?.metrics?.companies) }}</span></button><button :class="{active:tab==='finance'}" @click="tab='finance'"><WalletCards :size="18"/>Financial reports</button><button :class="{active:tab==='paymob'}" @click="tab='paymob'"><CreditCard :size="18"/>Paymob setup</button></nav><div class="platform-sidebar-bottom"><span><i></i>Platform secure</span><button @click="logout"><LogOut :size="16"/>Sign out</button></div></aside>
    <section class="platform-main"><header class="platform-topbar"><div><span class="platform-eyebrow">EXOUSIA REALTY / OWNER CONSOLE</span><h1>{{ tab==='overview'?'Platform overview':tab==='companies'?'Company directory':tab==='finance'?'Financial reports':'Paymob setup' }}</h1></div><div class="platform-top-actions"><span class="platform-live"><i></i>Live platform data</span><button class="platform-refresh" :disabled="loading" @click="load"><RefreshCw :size="15"/>Refresh</button></div></header>
      <div v-if="error" class="platform-error"><CircleAlert :size="16"/>{{ error }}</div><div v-if="loading" class="platform-loading">Loading platform intelligence…</div>
      <template v-else-if="overview">
        <section v-if="tab==='overview'" class="platform-content">
          <div class="platform-welcome"><div><span>{{new Intl.DateTimeFormat('en-EG',{weekday:'long'}).format(new Date()).toUpperCase()}} OPERATIONS BRIEF</span><h2>Your entire brokerage network,<br><em>at a glance.</em></h2><p>Company health, growth, and collected subscription revenue in one place.</p></div><div class="platform-welcome-mark"><div class="platform-orbit orbit-a"></div><div class="platform-orbit orbit-b"></div><Building2 :size="42"/><i></i></div></div>
          <div class="platform-kpis"><article><span class="kpi-icon gold"><Building2 :size="18"/></span><small>Registered companies</small><strong>{{count(overview.metrics.companies)}}</strong><span class="kpi-foot"><b>{{count(overview.metrics.active_companies)}}</b> paid and active</span></article><article><span class="kpi-icon green"><Users :size="18"/></span><small>People in workspaces</small><strong>{{count(overview.metrics.users)}}</strong><span class="kpi-foot"><b>{{count(overview.metrics.trial_companies)}}</b> companies on trial</span></article><article><span class="kpi-icon blue"><TrendingUp :size="18"/></span><small>Closed deal value</small><strong>{{money(overview.metrics.closed_deal_value_minor)}}</strong><span class="kpi-foot">Across {{count(overview.metrics.deals)}} recorded deals</span></article><article><span class="kpi-icon violet"><BadgeDollarSign :size="18"/></span><small>Subscription revenue</small><strong>{{money(overview.metrics.revenue_minor)}}</strong><span class="kpi-foot">{{count(overview.metrics.paid_payments)}} paid transactions in period</span></article></div><div class="platform-footprint"><span><Building2 :size="14"/>{{count(overview.metrics.listings)}} property listings</span><span><Users :size="14"/>{{count(overview.metrics.leads)}} leads across workspaces</span><span><WalletCards :size="14"/>{{count(overview.metrics.deals)}} deals recorded</span></div>
          <div class="platform-overview-grid"><section class="platform-panel platform-revenue"><header><div><span class="platform-eyebrow">COLLECTED REVENUE</span><h3>{{money(overview.metrics.revenue_minor)}}</h3><p>Paymob-confirmed payments · {{date(overview.from)}} to {{date(overview.to)}}</p></div><div class="platform-date-filter"><CalendarDays :size="14"/><input v-model="from" type="date"/><span>to</span><input v-model="to" type="date"/><button @click="loadOverview">Apply</button></div></header><div class="platform-chart"><div class="chart-y"><span>EGP {{money(Math.max(...(overview.revenue_series||[]).map((r:any)=>r.amount_minor),0)).replace('EGP','')}}</span><span>0</span></div><svg viewBox="0 0 1100 110" preserveAspectRatio="none"><defs><linearGradient id="revenueFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#b9955a" stop-opacity=".25"/><stop offset="1" stop-color="#b9955a" stop-opacity="0"/></linearGradient></defs><path :d="`M 0,100 L ${trendPoints.replaceAll(' ',' L ')} L 1100,110 L 0,110 Z`" fill="url(#revenueFill)"/><polyline :points="trendPoints" fill="none" stroke="#ad8951" stroke-width="2.5" vector-effect="non-scaling-stroke"/></svg><div class="chart-x"><span v-for="item in overview.revenue_series" :key="item.label">{{item.label}}</span></div></div></section><section class="platform-panel platform-plan-mix"><header><div><span class="platform-eyebrow">SUBSCRIPTION MIX</span><h3>Plans in service</h3></div><span class="plan-mix-total">{{count(overview.metrics.active_companies+overview.metrics.trial_companies)}}<small>current</small></span></header><div v-for="(plan,index) in overview.plan_mix" :key="plan.slug" class="plan-mix-row"><span class="plan-mix-dot" :class="`tone-${index}`"></span><span>{{plan.name}}</span><strong>{{plan.companies}}</strong><i><b :class="`tone-${index}`" :style="{width:`${Math.min(100,plan.companies/Math.max(1,overview.metrics.active_companies+overview.metrics.trial_companies)*100)}%`}"></b></i></div><div class="platform-small-stats"><span><b>{{count(overview.metrics.pending_payments)}}</b> pending payments</span><span><b>{{count(overview.metrics.suspended_companies)}}</b> suspended</span></div></section></div>
          <section class="platform-panel platform-table-panel"><header><div><span class="platform-eyebrow">NETWORK ACTIVITY</span><h3>Recently joined companies</h3><p>New brokerages joining the platform.</p></div><button class="platform-text-button" @click="tab='companies';loadCompanies()">View all companies <span>→</span></button></header><CompanyTable :companies="overview.companies" @manage="selected=$event;tab='companies';loadCompanies()"/></section>
          <section class="platform-panel platform-activity-panel"><header><div><span class="platform-eyebrow">CONTROL LOG</span><h3>Recent platform actions</h3></div><span class="platform-activity-count">{{overview.actions.length}} latest</span></header><div class="platform-activity-list"><article v-for="item in overview.actions" :key="item.id"><span class="activity-icon"><ShieldCheck :size="15"/></span><div><strong>{{item.action.split('_').join(' ')}}</strong><small>{{item.company}} · by {{item.admin}}</small></div><time>{{date(item.created_at)}}</time><span v-if="item.reason" class="activity-reason" :title="item.reason">Reason recorded</span></article><p v-if="!overview.actions.length" class="platform-empty">No platform changes have been made.</p></div></section>
        </section>

        <section v-if="tab==='companies'" class="platform-content"><div class="platform-section-intro"><span class="platform-eyebrow">YOUR CUSTOMER BASE</span><h2>Every brokerage, <em>one directory.</em></h2><p>Review account health, workspace activity, subscriptions, and owner contacts.</p></div><section class="platform-panel company-directory"><div class="company-toolbar"><label class="platform-search"><Search :size="16"/><input v-model="search" placeholder="Search company, owner, or email" @input="page=1;loadCompanies()"/></label><select v-model="statusFilter" @change="page=1;loadCompanies()"><option value="all">All account states</option><option value="active">Paid and active</option><option value="trial">Free trial</option><option value="expired">Expired</option><option value="suspended">Suspended</option></select><button class="platform-refresh" @click="downloadCompanies"><Download :size="15"/>Export page</button></div><CompanyTable :companies="companies" @manage="selected=$event"/><footer class="company-pagination"><span>Showing {{companies.length}} of {{count(totalCompanies)}} companies</span><div><button :disabled="page<=1" @click="changePage(-1)">Previous</button><b>{{page}} / {{lastPage}}</b><button :disabled="page>=lastPage" @click="changePage(1)">Next</button></div></footer></section></section>

        <section v-if="tab==='finance'" class="platform-content"><div class="platform-section-intro"><span class="platform-eyebrow">PORTAL FINANCIALS</span><h2>Clear view of <em>what came in.</em></h2><p>Only Paymob-confirmed subscription payments are counted as platform revenue. Manual access grants are tracked separately.</p></div><div class="platform-finance-filter"><label>From<input v-model="from" type="date"/></label><label>Through<input v-model="to" type="date"/></label><button class="platform-button-primary" @click="loadOverview"><CalendarDays :size="15"/>Run report</button></div><div class="platform-kpis finance-kpis"><article><span class="kpi-icon violet"><BadgeDollarSign :size="18"/></span><small>Collected revenue</small><strong>{{money(overview.metrics.revenue_minor)}}</strong><span class="kpi-foot">Paid subscription income only</span></article><article><span class="kpi-icon green"><Check :size="18"/></span><small>Successful payments</small><strong>{{count(overview.metrics.paid_payments)}}</strong><span class="kpi-foot">Settled transactions in selected range</span></article><article><span class="kpi-icon gold"><Clock3 :size="18"/></span><small>Awaiting confirmation</small><strong>{{count(overview.metrics.pending_payments)}}</strong><span class="kpi-foot">Open payment attempts platform-wide</span></article><article><span class="kpi-icon blue"><TrendingUp :size="18"/></span><small>Closed deal value</small><strong>{{money(overview.metrics.closed_deal_value_minor)}}</strong><span class="kpi-foot">Brokerage-reported EGP value, not portal revenue</span></article></div><section class="platform-panel platform-table-panel"><header><div><span class="platform-eyebrow">PAYMENT LEDGER</span><h3>Recent subscription transactions</h3><p>Payment attempts stay distinct from collected revenue.</p></div></header><div class="platform-table-scroll"><table class="platform-table"><thead><tr><th>Company</th><th>Plan and term</th><th>Payment status</th><th>Amount</th><th>Paid at</th></tr></thead><tbody><tr v-for="payment in overview.payments" :key="payment.id"><td><strong>{{payment.company}}</strong></td><td>{{payment.plan}} · {{payment.cycle==='year'?'Annual':'Monthly'}}</td><td><span class="platform-status" :class="payment.status"><i></i>{{payment.status}}</span></td><td class="money-cell">{{money(payment.amount_minor)}}</td><td>{{date(payment.paid_at||payment.created_at)}}</td></tr><tr v-if="!overview.payments.length"><td colspan="5" class="platform-empty">No subscription payment attempts yet.</td></tr></tbody></table></div></section></section>

        <section v-if="tab==='paymob'" class="platform-content">
          <div class="platform-section-intro"><span class="platform-eyebrow">PLATFORM OWNER ONLY</span><h2>Payment gateway <em>connection.</em></h2><p>Values are loaded from .env when present. Saving here keeps an encrypted dashboard override, which takes priority over .env.</p></div>
          <section class="platform-panel platform-action-form paymob-settings">
            <header><div><span class="platform-eyebrow">GATEWAY STATUS</span><h3>{{gateway.configured?'Paymob is ready for checkout':'Paymob needs configuration'}}</h3><p>{{gateway.source==='environment'?'Using values from .env. You can edit them here and save an encrypted dashboard override.':gateway.configured?'Encrypted dashboard settings are active.':'Companies cannot start online payments until valid credentials are saved.'}}</p></div><span class="platform-status" :class="gateway.configured?'active':'expired'"><i></i>{{gateway.configured?'Configured':'Not configured'}}</span></header>
            <form @submit.prevent="saveGateway">
              <div class="platform-form-row"><label>API secret / key<input v-model="gatewayForm.secret_key" type="password" autocomplete="new-password" placeholder="Loaded from .env or enter the Paymob API key"/></label><label>Public key for Unified Checkout<input v-model="gatewayForm.public_key" type="password" autocomplete="new-password" placeholder="Required only for Unified Checkout"/></label></div>
              <div class="platform-form-row"><label>HMAC secret<input v-model="gatewayForm.hmac_secret" type="password" autocomplete="new-password" placeholder="Loaded from .env or enter the HMAC secret"/></label><label>Integration IDs<input v-model="gatewayForm.payment_methods" required placeholder="Loaded from .env or enter IDs"/><small>Comma-separated Paymob payment integration IDs.</small></label></div>
              <div class="platform-form-row"><label>Iframe ID for Classic Checkout<input v-model="gatewayForm.iframe_id" placeholder="Used with the classic Paymob iframe flow"/></label><label>API base URL<input v-model="gatewayForm.api_base" type="url" required/></label></div>
              <div class="platform-form-row"><label>Hosted checkout URL<input v-model="gatewayForm.checkout_base" type="url" required/></label></div>
              <div class="platform-action-buttons"><button type="submit" class="platform-button-primary" :disabled="saving"><CreditCard :size="15"/>{{saving?'Saving securely…':'Save Paymob settings'}}</button></div>
            </form>
          </section>          
        </section>
      </template>
    </section>

    <div v-if="selected" class="platform-modal-backdrop" @click.self="selected=null;action=null"><section class="platform-company-modal"><header><div><span class="platform-eyebrow">BROKERAGE PROFILE / #{{selected.id}}</span><h2>{{selected.name}}</h2><p>{{selected.slug}} · Joined {{date(selected.created_at)}}</p></div><button class="platform-icon-button" @click="selected=null;action=null"><X :size="18"/></button></header><div class="company-modal-owner"><span class="platform-avatar">{{(selected.owner?.name||'?').slice(0,1).toUpperCase()}}</span><span><small>COMPANY OWNER</small><strong>{{selected.owner?.name||'No active owner'}}</strong><a v-if="selected.owner" :href="`mailto:${selected.owner.email}`">{{selected.owner.email}}</a></span><span class="platform-status" :class="selected.status"><i></i>{{statusName(selected.status)}}</span></div><div class="company-modal-kpis"><div><small>Plan</small><strong>{{selected.plan||'None'}}</strong></div><div><small>Subscription through</small><strong>{{date(selected.subscription_ends_at)}}</strong></div><div><small>Team members</small><strong>{{selected.active_members}}</strong></div><div><small>Inventory</small><strong>{{selected.listings}} listings</strong></div><div><small>Leads</small><strong>{{selected.leads}}</strong></div><div><small>Deals</small><strong>{{selected.deals}}</strong></div></div><p v-if="selected.suspension_reason" class="company-suspension-reason"><ShieldOff :size="15"/>{{selected.suspension_reason}}</p><div v-if="!action" class="company-modal-actions"><button class="platform-button-primary" @click="openAction(selected,'renew')"><RefreshCw :size="15"/>Grant or renew access</button><button v-if="!selected.is_suspended" class="platform-button-danger" @click="openAction(selected,'suspend')"><ShieldOff :size="15"/>Suspend company</button><button v-else class="platform-button-primary pale" :disabled="saving" @click="reactivate(selected)"><Check :size="15"/>Reactivate company</button><small>Manual access grants are audited and do not create a payment record.</small></div><form v-else class="platform-action-form" @submit.prevent="submitAction"><h3>{{action==='suspend'?'Suspend company access':'Grant subscription access'}}</h3><template v-if="action==='renew'"><div class="platform-form-row"><label>Plan<select v-model.number="form.plan_id" required><option v-for="plan in plans" :key="plan.id" :value="plan.id">{{plan.name}}</option></select></label><label>Billing term<select v-model="form.billing_cycle"><option value="month">Monthly</option><option value="year">Yearly</option></select></label></div><div class="platform-form-row"><label>Periods<input v-model.number="form.periods" type="number" min="1" max="24" required/></label><label>Starts<select v-model="form.renewal_mode"><option value="extend">After current access</option><option value="today">Immediately</option></select></label></div></template><label>Reason / admin note<textarea v-model="form.reason" required maxlength="1000" rows="3" :placeholder="action==='suspend'?'Explain why this company is being suspended.':'Record the reason for this complimentary or corrected access grant.'"/></label><div class="platform-action-buttons"><button type="button" class="platform-button-quiet" @click="action=null">Cancel</button><button type="submit" :class="action==='suspend'?'platform-button-danger':'platform-button-primary'" :disabled="saving">{{saving?'Saving…':action==='suspend'?'Confirm suspension':'Grant access'}}</button></div></form></section></div>
  </main>
</template>

<script lang="ts">
import { defineComponent, h } from 'vue'
const CompanyTable = defineComponent({
  props: { companies: { type: Array, required: true } },
  emits: ['manage'],
  setup(props, { emit }) { return () => h('div',{class:'platform-table-scroll'},[h('table',{class:'platform-table'},[
    h('thead',[h('tr',['Company / owner','Status','Plan / access ends','Members','Leads','Listings',''].map((v)=>h('th',v)))]),
    h('tbody',(props.companies as any[]).length?(props.companies as any[]).map(company=>h('tr',{key:company.id},[
      h('td',{class:'company-cell'},[h('span',{class:'company-table-avatar'},company.name.slice(0,1).toUpperCase()),h('span',[h('strong',company.name),h('small',company.owner?.email||company.slug)])]),
      h('td',[h('span',{class:`platform-status ${company.status}`},[h('i'),company.status==='active'?'Paid':company.status==='trial'?'Free trial':company.status==='suspended'?'Suspended':company.status==='expired'?'Expired':'No plan'])]),
      h('td',[h('strong',company.plan||'No plan'),h('small',{class:'table-subline'},company.subscription_ends_at?`Through ${new Intl.DateTimeFormat('en-EG',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(company.subscription_ends_at))}`:'No active term')]),
      h('td',String(company.active_members)),h('td',String(company.leads)),h('td',String(company.listings)),
      h('td',[h('button',{class:'platform-manage-button',onClick:()=>emit('manage',company)},'Manage →')]),
    ])): [h('tr',[h('td',{colspan:7,class:'platform-empty'},'No companies match these filters.')])])
  ])]) }
})
export default { components: { CompanyTable } }
</script>
